// leaf_proc runs the leaf_proc Golang process.
//
// leaf_proc is auto-generated by Blueprint's goproc plugin (goproc/goprocgen/main.go.go)
//
// Usage:
//
//   go run main.go --leaf_db.dial_addr=value --zipkin.dial_addr=value --leaf_service.http.bind_addr=value 
//
// Optional env: GC_INTERVAL_SEC=N (e.g. 30, 1, 0.5, 0.1) to run GC every N seconds; fractional seconds supported. Omit or <=0 for default GC.
//
// leaf_proc requires the following arguments are passed:
//
//   --leaf_db.dial_addr
//       Auto-generated by Blueprint IR node:
//       leaf_db.dial_addr = AddressConfig()
//
//   --zipkin.dial_addr
//       Auto-generated by Blueprint IR node:
//       zipkin.dial_addr = AddressConfig()
//
//   --leaf_service.http.bind_addr
//       Auto-generated by Blueprint IR node:
//       leaf_service.http.bind_addr = AddressConfig()
//
// leaf_proc will instantiate the following IR nodes:
//   leaf_proc.stdoutmetriccollector
//   leaf_proc.logger
//   leaf_cache
//   leaf_db.client
//   leaf_service
//   zipkin.client
//   leaf_service.server.ot
//   leaf_service.http_server
package main

import (
	"context"
	"os"
	"runtime"
	"strconv"
	"time"

	"log/slog"
)

func main() {
	// Optional: run GC on a fixed interval to normalize GC frequency (e.g. across tracing vs no-tracing).
	// Set GC_INTERVAL_SEC to a positive number (e.g. 30, 1, 0.5, 0.1) to trigger runtime.GC() every N seconds; unset or <=0 to leave default GC behavior.
	if sec := os.Getenv("GC_INTERVAL_SEC"); sec != "" {
		if secVal, err := strconv.ParseFloat(sec, 64); err == nil && secVal > 0 && secVal < 1e15 {
			interval := time.Duration(secVal * float64(time.Second))
			if interval > 0 {
				go func() {
					ticker := time.NewTicker(interval)
					defer ticker.Stop()
					for range ticker.C {
						runtime.GC()
					}
				}()
			}
		}
	}
	slog.Info("Running leaf_proc")
	n, err := New_leaf_proc("leaf_proc").Build(context.Background())
	if err != nil {
		slog.Error(err.Error())
		os.Exit(1)
	}
	n.Await()
	slog.Info("leaf_proc exiting")
}